/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Int32Array = require( '@stdlib/array/int32' );
var Float64Array = require( '@stdlib/array/float64' );
var EPS = require( '@stdlib/constants/float64/eps' );
var abs = require( '@stdlib/math/base/special/abs' );
var dgtts2 = require( './../lib/dgtts2.js' );


// FIXTURES //

var COL_MAJOR_NO_OFFSET_TRANS = require( './fixtures/col_major_no_offset_trans.json' );
var COL_MAJOR_NO_OFFSET_NO_TRANS = require( './fixtures/col_major_no_offset_no_trans.json' );
var ROW_MAJOR_NO_OFFSET_TRANS = require( './fixtures/row_major_no_offset_trans.json' );
var ROW_MAJOR_NO_OFFSET_NO_TRANS = require( './fixtures/row_major_no_offset_no_trans.json' );


// FUNCTIONS //

/**
* Tests for element-wise approximate equality.
*
* @private
* @param {Object} t - test object
* @param {Collection} actual - actual values
* @param {Collection} expected - expected values
* @param {number} rtol - relative tolerance
*/
function isApprox( t, actual, expected, rtol ) {
	var delta;
	var tol;
	var i;

	t.strictEqual( actual.length, expected.length, 'returns expected value' );
	for ( i = 0; i < expected.length; i++ ) {
		if ( actual[ i ] === expected[ i ] ) {
			t.strictEqual( actual[ i ], expected[ i ], 'returns expected value' );
		} else {
			delta = abs( actual[ i ] - expected[ i ] );
			tol = rtol * EPS * abs( expected[ i ] );
			t.ok( delta <= tol, 'within tolerance. actual: '+actual[ i ]+'. expected: '+expected[ i ]+'. delta: '+delta+'. tol: '+tol+'.' );
		}
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dgtts2, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 11', function test( t ) {
	t.strictEqual( dgtts2.length, 11, 'returns expected value' );
	t.end();
});

tape( 'the function throws an error if provided a first argument which is not a valid order', function test( t ) {
	var values;
	var data;
	var i;

	data = COL_MAJOR_NO_OFFSET_TRANS;

	values = [
		'foo',
		'bar',
		'beep',
		'boop',
		-5,
		NaN,
		true,
		false,
		null,
		void 0,
		[],
		{},
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dgtts2( value, data.itrans, data.N, data.nrhs, data.DL, data.D, data.DU, data.DU2, data.IPIV, data.B, data.LDB );
		};
	}
});

tape( 'the function throws an error if provided an eleventh argument which is not a valid `LDA` value (row-major)', function test( t ) {
	var values;
	var data;
	var i;

	data = ROW_MAJOR_NO_OFFSET_TRANS;

	values = [
		0,
		1,
		2
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), RangeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			dgtts2( data.order, data.itrans, data.N, data.nrhs, data.DL, data.D, data.DU, data.DU2, data.IPIV, data.B, value );
		};
	}
});

tape( 'the function returns the input array unchanged if N is zero', function test( t ) {
	var IPIV;
	var data;
	var DU2;
	var DU;
	var DL;
	var D;
	var B;
	var X;

	data = ROW_MAJOR_NO_OFFSET_NO_TRANS;

	DL = new Float64Array( data.DL );
	D = new Float64Array( data.D );
	DU = new Float64Array( data.DU );
	DU2 = new Float64Array( data.DU2 );
	IPIV = new Int32Array( data.IPIV );
	B = new Float64Array( data.B );

	X = dgtts2( data.order, data.itrans, 0, data.nrhs, DL, D, DU, DU2, IPIV, B, data.LDB );
	t.deepEqual( B, X );

	t.end();
});

tape( 'the function solves A * X = B (row-major)', function test( t ) {
	var expectedX;
	var IPIV;
	var data;
	var DU2;
	var DU;
	var DL;
	var D;
	var B;
	var X;

	data = ROW_MAJOR_NO_OFFSET_NO_TRANS;

	DL = new Float64Array( data.DL );
	D = new Float64Array( data.D );
	DU = new Float64Array( data.DU );
	DU2 = new Float64Array( data.DU2 );
	IPIV = new Int32Array( data.IPIV );
	B = new Float64Array( data.B );

	X = dgtts2( data.order, data.itrans, data.N, data.nrhs, DL, D, DU, DU2, IPIV, B, data.LDB );

	expectedX = new Float64Array( data.expected );
	isApprox( t, X, expectedX, 1.0 );

	t.end();
});

